def variants(a):
    im=Image.open(a['image_src']).convert('RGB')
    ratio=3/2
    if im.width/im.height>ratio:
        w=round(im.height*ratio); x=(im.width-w)//2; im=im.crop((x,0,x+w,im.height))
    else:
        h=round(im.width/ratio); y=(im.height-h)//2; im=im.crop((0,y,im.width,y+h))
    out=ROOT/'assets/images/editorial-auto'; out.mkdir(parents=True,exist_ok=True)
    vs=[]
    for w in (480,800,1200):
        p=out/f"{a['image_key']}-{w}.webp"; im.resize((w,round(w*2/3)),Image.Resampling.LANCZOS).save(p,'WEBP',quality=88,method=6)
        vs.append({'w':w,'src':'/assets/images/editorial-auto/'+p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size})
    return vs

